//! llama.cpp and whisper.cpp, linked against one shared ggml. `ffi` is generated by
//! `scripts/generate-inference-bindings.sh`; the functions below are the safe subset the
//! app uses so far.

use std::ffi::{CStr, CString, c_char};
use std::path::Path;
use std::sync::Once;

#[allow(
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    dead_code,
    clippy::all
)]
pub mod ffi {
    include!("bindings.rs");
}

fn owned(ptr: *const c_char) -> String {
    // SAFETY: both engines return pointers to static, NUL-terminated strings.
    unsafe { CStr::from_ptr(ptr) }
        .to_string_lossy()
        .into_owned()
}

/// CPU features ggml was compiled with, as reported by llama.cpp.
pub fn llama_system_info() -> String {
    owned(unsafe { ffi::llama_print_system_info() })
}

/// CPU features ggml was compiled with, as reported by whisper.cpp.
pub fn whisper_system_info() -> String {
    owned(unsafe { ffi::whisper_print_system_info() })
}

fn c_path(path: &Path) -> Option<CString> {
    CString::new(path.to_str()?).ok()
}

/// Loads and immediately frees a GGUF model; true if llama.cpp accepted the file.
pub fn llama_model_loads(path: &Path) -> bool {
    static BACKEND: Once = Once::new();
    BACKEND.call_once(|| unsafe { ffi::llama_backend_init() });
    let Some(path) = c_path(path) else {
        return false;
    };
    unsafe {
        let model =
            ffi::llama_model_load_from_file(path.as_ptr(), ffi::llama_model_default_params());
        if model.is_null() {
            return false;
        }
        ffi::llama_model_free(model);
    }
    true
}

/// Loads and immediately frees a ggml Whisper model; true if whisper.cpp accepted the file.
pub fn whisper_model_loads(path: &Path) -> bool {
    let Some(path) = c_path(path) else {
        return false;
    };
    unsafe {
        let ctx = ffi::whisper_init_from_file_with_params(
            path.as_ptr(),
            ffi::whisper_context_default_params(),
        );
        if ctx.is_null() {
            return false;
        }
        ffi::whisper_free(ctx);
    }
    true
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::path::PathBuf;

    fn model(name: &str) -> PathBuf {
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../models")
            .join(name)
    }

    #[test]
    fn both_engines_report_system_info() {
        assert!(llama_system_info().contains("CPU"));
        assert!(whisper_system_info().contains("WHISPER"));
    }

    #[test]
    fn missing_model_files_are_rejected() {
        assert!(!llama_model_loads(Path::new("/nonexistent.gguf")));
        assert!(!whisper_model_loads(Path::new("/nonexistent.bin")));
    }

    #[test]
    #[ignore = "needs scripts/fetch-models.sh"]
    fn bundled_llama_model_loads() {
        assert!(llama_model_loads(&model(
            "Llama-3.2-1B-Instruct-Q4_K_M.gguf"
        )));
    }

    #[test]
    #[ignore = "needs scripts/fetch-models.sh"]
    fn bundled_whisper_model_loads() {
        assert!(whisper_model_loads(&model("ggml-small-q5_1.bin")));
    }
}
